package com.starlight.greetings.application;
import com.starlight.greetings.domain.auth.PasswordHasher; import com.starlight.greetings.domain.auth.SignupValidator; import com.starlight.greetings.web.ApiException; import com.starlight.greetings.web.SignupResult; import java.nio.*; import java.io.ByteArrayOutputStream; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import javax.crypto.*; import javax.crypto.spec.GCMParameterSpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class JdbcAdminLoginService implements AdminLoginService {private final JdbcTemplate jdbc;private final String key;private final SignupValidator valid=new SignupValidator();private final PasswordHasher hash=new PasswordHasher();private final SecureRandom random=new SecureRandom();public JdbcAdminLoginService(JdbcTemplate jdbc,@Value("${ADMIN_TOTP_KEY:}")String key){this.jdbc=jdbc;this.key=key;}
 @Transactional public SignupResult login(String nickname,String password,String code){if(key.isBlank())throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"SERVICE_UNAVAILABLE","운영자 로그인을 이용할 수 없습니다.");var name=valid.nickname(nickname);password=valid.password(password);var users=jdbc.query("select id,nickname,password_hash,totp_secret_ciphertext,last_totp_step from users where nickname_key=? and role='admin' and status='active' for update",(r,i)->new Object[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getLong(5)},name.key());if(users.isEmpty()||!hash.matches((String)users.get(0)[2],password))throw fail();String secret;try{secret=decrypt((String)users.get(0)[3]);}catch(Exception e){throw fail();}long step=verify(secret,code,(Long)users.get(0)[4]);if(step<0)throw fail();String id=(String)users.get(0)[0],session=token(),csrf=token();jdbc.update("update users set last_totp_step=? where id=?::uuid",step,id);jdbc.update("insert into sessions(id,user_id,token_hash,csrf_hash,csrf_token,expires_at,admin_verified_at) values(?::uuid,?::uuid,?,?,?,now()+interval '12 hours',now())",UUID.randomUUID().toString(),id,digest(session),digest(csrf),csrf);return new SignupResult(id,(String)users.get(0)[1],null,csrf,session);}
 private String decrypt(String encrypted)throws Exception{String[] p=encrypted.split("\\.");if(p.length!=3)throw new GeneralSecurityException();byte[] raw=Base64.getDecoder().decode(key);if(raw.length!=32)throw new GeneralSecurityException();byte[] ciphertext=Base64.getUrlDecoder().decode(p[2]),tag=Base64.getUrlDecoder().decode(p[1]),combined=java.util.Arrays.copyOf(ciphertext,ciphertext.length+tag.length);System.arraycopy(tag,0,combined,ciphertext.length,tag.length);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new javax.crypto.spec.SecretKeySpec(raw,"AES"),new GCMParameterSpec(128,Base64.getUrlDecoder().decode(p[0])));return new String(cipher.doFinal(combined),StandardCharsets.UTF_8);}
 private long verify(String secret,String code,long last){if(code==null||!code.matches("\\d{6}"))return -1;byte[] key=base32(secret);long now=System.currentTimeMillis()/30000;for(long n:List.of(now-1,now,now+1)){if(n<=last||n<0)continue;if(totp(key,n).equals(code))return n;}return -1;}
 private byte[] base32(String s){String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";if(!s.matches("[A-Z2-7]{32}"))throw new IllegalArgumentException();ByteArrayOutputStream out=new ByteArrayOutputStream();int bits=0,value=0;for(char c:s.toCharArray()){value=(value<<5)|alphabet.indexOf(c);bits+=5;if(bits>=8){out.write((value>>(bits-8))&255);bits-=8;}}return out.toByteArray();} private String totp(byte[] key,long counter){try{ByteBuffer b=ByteBuffer.allocate(8);b.putLong(counter);Mac mac=Mac.getInstance("HmacSHA1");mac.init(new javax.crypto.spec.SecretKeySpec(key,"HmacSHA1"));byte[] h=mac.doFinal(b.array());int o=h[h.length-1]&15,n=((h[o]&127)<<24)|((h[o+1]&255)<<16)|((h[o+2]&255)<<8)|(h[o+3]&255);return String.format("%06d",n%1000000);}catch(Exception e){throw new IllegalStateException(e);}} private String token(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String digest(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private ApiException fail(){return new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","로그인 정보를 확인해 주세요.");}}
